import os
import torch


class Config:
    """
    Configuration for the Global-Normed Projected-Context Residual Network (GPCR-Net).
    Centralizes file paths, hyperparameters, and statistical constants.
    """

    # -------------------------------------------------------------------------
    # File Paths
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files (Generated by the provided metadata script)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")
    SAMPLE_SUBMISSION = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Working Directories (Idea 44 specific)
    WORKING_DIR = "./working/idea_44"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_FILE = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Checkpoint Path
    BEST_MODEL_PATH = os.path.join(CHECKPOINT_DIR, "best_model.pth")

    # -------------------------------------------------------------------------
    # Global Statistical Constants (Target Normalization)
    # -------------------------------------------------------------------------
    # Derived from the analysis of the entire training history (1109 rows).
    # Used to Z-score normalize the target FVC.
    TARGET_MEAN = 2654.6528
    TARGET_STD = 801.7017

    # Feature Normalization Constants (Approximate from EDA)
    AGE_MEAN = 67.58
    AGE_STD = 6.63

    # -------------------------------------------------------------------------
    # Preprocessing Constants
    # -------------------------------------------------------------------------
    # Radiological Windowing (Lung Window)
    WINDOW_LEVEL = -600
    WINDOW_WIDTH = 1500

    # Image Sizing
    IMG_SIZE = 260  # Native resolution for EfficientNet-B2

    # Time Scaling
    # Relative time is scaled by 0.01 (e.g., 10 weeks -> 0.1)
    TIME_SCALE = 0.01

    # -------------------------------------------------------------------------
    # Model Hyperparameters
    # -------------------------------------------------------------------------
    MODEL_NAME = "efficientnet_b2"

    # Dimensions
    IMG_EMBED_DIM = 64
    # Clinical Features: Baseline_FVC, Relative_Time, Age, Sex, SmokingStatus
    N_CLINICAL_FEATURES = 5

    # -------------------------------------------------------------------------
    # Training Hyperparameters
    # -------------------------------------------------------------------------
    SEED = 42
    EPOCHS = 50
    BATCH_SIZE = 32  # Constraint: >= 32
    NUM_WORKERS = 4  # 12 vCPUs available

    # Optimization
    LR_BACKBONE = 1e-4
    LR_HEAD = 1e-3
    WEIGHT_DECAY = 1e-2

    # Scheduler
    T_MAX = EPOCHS  # For Cosine Annealing

    # -------------------------------------------------------------------------
    # Hardware
    # -------------------------------------------------------------------------
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    @classmethod
    def setup(cls):
        """
        Initializes the environment:
        1. Creates necessary directories.
        2. Sets random seeds for reproducibility.
        """
        # Create directories
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.CHECKPOINT_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set seeds
        os.environ["PYTHONHASHSEED"] = str(cls.SEED)
        torch.manual_seed(cls.SEED)
        if torch.cuda.is_available():
            torch.cuda.manual_seed(cls.SEED)
            torch.cuda.manual_seed_all(cls.SEED)
            torch.backends.cudnn.deterministic = True
            torch.backends.cudnn.benchmark = False
